WHERE {
  ?professor a uni:Professor ;
             uni:hasName ?professorName .

  {
    ?professor a uni:FullProfessor .
  }
  UNION
  {
    ?professor uni:hasRank ?rank .
    FILTER(LCASE(STR(?rank)) = "full professor" || LCASE(STR(?rank)) = "full")
